89			PublicInputs: math.MaxInt, PrivateInputs: 1}); !errors.Is(err, ErrInvalidArgument) {
90			t.Fatalf("want ErrInvalidArgument, got %v", err)
91		}
92		if err := s2.Close(); err != nil {
93			t.Fatal(err)
94		}
