104	// TestFullUpdateOverflowRejected: the whole-record replacement judges the
105	// supplied counts before looking the version up, so an unrepresentable
106	// replacement is invalid even for an unknown or a frozen version, and on a
107	// live draft the whole change (counts and description) is refused together.
108	func TestFullUpdateOverflowRejected(t *testing.T) {
109		s := openTestStore(t)
110		seedPartialDraft(t, s, "c") // 2 constraints, 1 public, 3 private, "初稿"
111	
112		overflow := Circuit{Name: "c", Version: 1, Constraints: 2,
113			PublicInputs: math.MaxInt, PrivateInputs: 1, Description: "new"}
114		if _, err := s.UpdateCircuit(overflow); !errors.Is(err, ErrInvalidArgument) {
115			t.Fatalf("overflow full update on a draft: want invalid, got %v", err)
116		}
117		got, _ := s.GetCircuit("c", 1)
118		if got.Constraints != 2 || got.PublicInputs != 1 || got.PrivateInputs != 3 || got.Description != "初稿" {
119			t.Fatalf("rejected full update leaked: %+v", got)
120		}
121	
122		// Counts judged before existence: unknown version still reports invalid.
123		unknown := overflow
124		unknown.Version = 9
125		if _, err := s.UpdateCircuit(unknown); !errors.Is(err, ErrInvalidArgument) {
126			t.Fatalf("overflow full update on unknown version: want invalid, got %v", err)
127		}
128	
129		// Counts judged before frozen state: a frozen target still reports invalid.
130		if _, err := s.FreezeCircuit("c", 1); err != nil {
131			t.Fatal(err)
132		}
133		if _, err := s.UpdateCircuit(overflow); !errors.Is(err, ErrInvalidArgument) {
134			t.Fatalf("overflow full update on frozen version: want invalid, got %v", err)
135		}
136	}
137	
138	// TestPartialUpdateOverflowMergesRetainedCounts covers the headline partial
139	// rule: changing only one input count still judges it together with the
140	// retained other count, and any description carried in the same change is
141	// refused with it.
142	func TestPartialUpdateOverflowMergesRetainedCounts(t *testing.T) {
143		s := openTestStore(t)
144		seedPartialDraft(t, s, "c") // 1 public, 3 private
145		M := math.MaxInt
146	
147		// Only the public count is supplied; the retained 3 private inputs push it
148		// over the bound.
149		if _, err := s.UpdateCircuitPartial("c", 1, PartialCircuit{
150			PublicInputs: intPtr(M), Description: stringPtr("x"),
151		}); !errors.Is(err, ErrInvalidArgument) {
152			t.Fatalf("public=M with retained private=3: want invalid, got %v", err)
153		}
154		// Only the private count is supplied; the retained 1 public input pushes.
155		if _, err := s.UpdateCircuitPartial("c", 1, PartialCircuit{
156			PrivateInputs: intPtr(M),
157		}); !errors.Is(err, ErrInvalidArgument) {
158			t.Fatalf("private=M with retained public=1: want invalid, got %v", err)
159		}
160		// Counts and description all stay as they were; nothing committed.
161		got, _ := s.GetCircuit("c", 1)
162		if got.Constraints != 2 || got.PublicInputs != 1 || got.PrivateInputs != 3 || got.Description != "初稿" {
163			t.Fatalf("rejected partial update leaked: %+v", got)
164		}
165	
166		// The exact boundary through a partial edit is still reachable: zero the
167		// retained private inputs first, then take public to M-1.
168		if _, err := s.UpdateCircuitPartial("c", 1, PartialCircuit{
169			PrivateInputs: intPtr(0),
170		}); err != nil {
171			t.Fatal(err)
172		}
173		edge, err := s.UpdateCircuitPartial("c", 1, PartialCircuit{
174			PublicInputs: intPtr(M - 1),
175		})
176		if err != nil {
177			t.Fatalf("public=M-1 with private=0 must be legal: %v", err)
178		}
179		if edge.PublicInputs != M-1 || edge.PrivateInputs != 0 {
180			t.Fatalf("boundary partial update wrong: %+v", edge)
181		}
182	
183		// Explicit zero supplied on the other side while at M-1 stays zero and is
184		// not conflated with "omitted".
185		again, err := s.UpdateCircuitPartial("c", 1, PartialCircuit{
186			PrivateInputs: intPtr(0),
187		})
188		if err != nil {
189			t.Fatalf("explicit zero private at the boundary: %v", err)
190		}
191		if again.PublicInputs != M-1 || again.PrivateInputs != 0 {
192			t.Fatalf("explicit zero leaked: %+v", again)
193		}
194	}
195	
196	// TestPartialUpdateGatingOrderWithOverflow preserves the existing judgment
197	// order: unknown versions report not found and frozen versions frozen even
198	// when the merged counts would be unrepresentable.
199	func TestPartialUpdateGatingOrderWithOverflow(t *testing.T) {
200		s := openTestStore(t)
201		if _, err := s.UpdateCircuitPartial("ghost", 1, PartialCircuit{
202			PublicInputs: intPtr(math.MaxInt),
203		}); !errors.Is(err, ErrNotFound) {
