205		}
206	
207		seedPartialDraft(t, s, "c") // 1 public, 3 private
208		if _, err := s.FreezeCircuit("c", 1); err != nil {
209			t.Fatal(err)
210		}
211		// public=M merged with the frozen record's private=3 would overflow, but
212		// the frozen state is settled first.
213		if _, err := s.UpdateCircuitPartial("c", 1, PartialCircuit{
214			PublicInputs: intPtr(math.MaxInt),
215		}); !errors.Is(err, ErrFrozen) {
216			t.Fatalf("frozen version: want frozen, got %v", err)
217		}
218	}
219	
220	// TestPartialOverflowWithImportedDefinition refuses the whole change on a
221	// version that already carries a definition, leaving the imported definition
222	// byte-for-byte usable.
223	func TestPartialOverflowWithImportedDefinition(t *testing.T) {
224		s := openTestStore(t)
225		// 1 constraint, 1 public + 1 private, a term-free definition.
226		seedDraftWithDef(t, s, "c", 1, 1, 1, emptySidesDef)
227	
228		if _, err := s.UpdateCircuitPartial("c", 1, PartialCircuit{
229			PublicInputs: intPtr(math.MaxInt),
230		}); !errors.Is(err, ErrInvalidArgument) {
231			t.Fatalf("overflow partial with definition: want invalid, got %v", err)
232		}
233		stored, _ := s.GetCircuit("c", 1)
234		if stored.PublicInputs != 1 || stored.PrivateInputs != 1 {
235			t.Fatalf("counts changed after refused update: %+v", stored)
236		}
237		def, err := s.GetDefinition("c", 1)
238		if err != nil || len(def.Constraints) != 1 {
239			t.Fatalf("imported definition damaged: %+v %v", def, err)
240		}
241	}
242	
243	// TestBoundaryLayoutPersistsAcrossReload: public M-1, private 0 creates,
244	// queries, survives a reload and stays editable, exercising the exact
245	// representable edge without allocating the (impossibly large) wire array.
246	func TestBoundaryLayoutPersistsAcrossReload(t *testing.T) {
247		dir := filepath.Join(t.TempDir(), "bench")
248		s, err := Open(dir)
249		if err != nil {
250			t.Fatal(err)
251		}
252		created, err := s.CreateCircuit(Circuit{Name: "edge", Version: 1, Constraints: 1,
253			PublicInputs: math.MaxInt - 1, PrivateInputs: 0, Description: "edge"})
254		if err != nil {
255			t.Fatalf("create M-1,0: %v", err)
256		}
257		if created.PublicInputs != math.MaxInt-1 {
258			t.Fatalf("created count drifted: %d", created.PublicInputs)
259		}
260		if _, err := s.GetCircuit("edge", 1); err != nil {
261			t.Fatalf("query boundary record: %v", err)
262		}
263		if err := s.Close(); err != nil {
264			t.Fatal(err)
265		}
266	
267		s2, err := Open(dir)
268		if err != nil {
269			t.Fatalf("reload boundary record: %v", err)
270		}
271		defer s2.Close()
272		got, err := s2.GetCircuit("edge", 1)
273		if err != nil {
274			t.Fatalf("query after reload: %v", err)
275		}
276		if got.PublicInputs != math.MaxInt-1 || got.PrivateInputs != 0 {
277			t.Fatalf("reloaded boundary record drifted: %+v", got)
278		}
279	}
280	
281	// TestZeroInputsEmptySidesDefinitionUnchanged pins the constant-wire layout
282	// and the no-regression path: zero public and zero private inputs still name
283	// wire 0, an all-empty a/b/c definition imports, compiles and re-hashes
284	// identically across a reload.
285	func TestZeroInputsEmptySidesDefinitionUnchanged(t *testing.T) {
286		dir := filepath.Join(t.TempDir(), "bench")
287		s, err := Open(dir)
288		if err != nil {
289			t.Fatal(err)
290		}
291		if _, err := s.CreateCircuit(Circuit{Name: "z", Version: 1, Constraints: 1,
292			PublicInputs: 0, PrivateInputs: 0}); err != nil {
293			t.Fatal(err)
294		}
295		if _, err := s.ImportConstraints("z", 1, writeTempJSON(t, emptySidesDef)); err != nil {
296			t.Fatalf("term-free definition on 0/0 inputs: %v", err)
297		}
298		if _, err := s.FreezeCircuit("z", 1); err != nil {
299			t.Fatal(err)
300		}
301		first, err := s.CompileCircuit("z", 1)
302		if err != nil {
303			t.Fatalf("compile 0/0: %v", err)
304		}
305		if err := s.Close(); err != nil {
306			t.Fatal(err)
307		}
308	
309		s2, err := Open(dir)
310		if err != nil {
311			t.Fatalf("reload 0/0 record: %v", err)
312		}
313		defer s2.Close()
314		again, err := s2.CompileCircuit("z", 1)
315		if err != nil {
316			t.Fatalf("recompile after reload: %v", err)
317		}
318		if again.Hash != first.Hash {
319			t.Fatalf("compile hash changed across reload: %q vs %q", first.Hash, again.Hash)
320		}
321	}
322	
323	// TestOverflowRecordRefusedOnLoad: a committed record whose declared input
324	// layout cannot be represented (here M-1 public bumped to 1 private, summing
325	// past M once the constant wire is counted) makes the whole directory
326	// unreadable with ErrDataCorrupt; no query returns partial results and the
327	// original file is left byte-for-byte in place.
328	func TestOverflowRecordRefusedOnLoad(t *testing.T) {
329		dir := filepath.Join(t.TempDir(), "bench")
330		s, err := Open(dir)
331		if err != nil {
332			t.Fatal(err)
333		}
334		if _, err := s.CreateCircuit(Circuit{Name: "edge", Version: 1, Constraints: 1,
335			PublicInputs: math.MaxInt - 1, PrivateInputs: 0}); err != nil {
336			t.Fatal(err)
337		}
338		if _, err := s.CreateCircuit(Circuit{Name: "healthy", Version: 1, Constraints: 1,
339			Description: "fine"}); err != nil {
340			t.Fatal(err)
341		}
342		if err := s.Close(); err != nil {
343			t.Fatal(err)
344		}
345	
346		env := readGenericEnv(t, dir)
347		for _, raw := range env["circuits"].([]any) {
348			rec := raw.(map[string]any)
349			if rec["name"] == "edge" {
350				// json.Number keeps the digits exact; a float64 round-trip would
351				// rewrite M-1 as an imprecise value the strict int decoder rejects
352				// before the layout rule is reached.
353				rec["public_inputs"] = json.Number(strconv.Itoa(math.MaxInt - 1))
354				rec["private_inputs"] = json.Number("1") // 1 + (M-1) + 1 = M+1
355			}
356		}
357		bad := writeGenericEnv(t, dir, env)
358	
359		got, err := Open(dir)
360		if err == nil {
361			got.Close()
362			t.Fatal("unrepresentable committed layout was accepted on load")
363		}
364		if !errors.Is(err, ErrDataCorrupt) {
365			t.Fatalf("want ErrDataCorrupt, got %v", err)
366		}
367		if !strings.Contains(err.Error(), "not representable") {
368			t.Fatalf("corruption error must name the layout limit: %v", err)
369		}
370		left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
371		if rerr != nil {
372			t.Fatal(rerr)
373		}
374		if string(left) != string(bad) {
375			t.Fatal("refused read modified data.json")
376		}
377	}
378	
379	// TestOverflowRecordWithDefinitionRefusedOnLoad reproduces the original
380	// failure mode: a term-free definition committed against overflowing counts
381	// imported cleanly only because public+private wrapped negative, and the next
382	// read reported corruption via a definition mismatch. The explicit layout
383	// rule now names the same condition directly and still refuses the read.
384	func TestOverflowRecordWithDefinitionRefusedOnLoad(t *testing.T) {
385		dir := filepath.Join(t.TempDir(), "bench")
386		s, err := Open(dir)
387		if err != nil {
388			t.Fatal(err)
389		}
390		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1,
391			PublicInputs: math.MaxInt - 1, PrivateInputs: 0}); err != nil {
392			t.Fatal(err)
393		}
394		if _, err := s.ImportConstraints("c", 1, writeTempJSON(t, emptySidesDef)); err != nil {
395			t.Fatal(err)
396		}
397		if err := s.Close(); err != nil {
398			t.Fatal(err)
399		}
400	
401		env := readGenericEnv(t, dir)
402		rec := readFirstCircuit(env)
403		// Keep both counts as exact digits: a float64 round-trip would fail the
404		// strict int decoder instead of reaching the layout rule.
405		rec["public_inputs"] = json.Number(strconv.Itoa(math.MaxInt - 1))
406		rec["private_inputs"] = json.Number("1") // 1 + (M-1) + 1 = M+1
407		writeGenericEnv(t, dir, env)
408	
409		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
410			t.Fatalf("overflow layout with definition: want ErrDataCorrupt, got %v", err)
411		}
412	}
